// /src/physics-core/PhysicsEngine.ts
import type { PhysicsCoreModule } from "./types";

// Import the factory function generated by Emscripten
// Note: You might need to use @ts-ignore if TS complains about the missing .d.ts for this JS file
// @ts-ignore
import loadWasm from "../wasm/physics.js";

export class PhysicsEngine {
  private wasmModule: PhysicsCoreModule | null = null;

  public async init(): Promise<void> {
    // 1. Call the Emscripten factory function to instantiate the Wasm binary
    this.wasmModule = await loadWasm();
    console.log("Wasm Module Loaded:", this.wasmModule);
  }

  public testAdd(a: number, b: number): number {
    if (!this.wasmModule) {
      throw new Error("PhysicsEngine not initialized! Call init() first.");
    }

    // 2. Call your C++ function exactly as if it were a JS function!
    return this.wasmModule.add(a, b);
  }
}
